// The two rules and the four bar segments (the "channels").
const RULE_TOP = { x: 471.7, y: 656.75, w: 881.9, h: 18.34 };
const RULE_BOT = { x: 576.72, y: 831.81, w: 776.88, h: 18.34 };
const SEG = { y: 693.35, w: 163.44, h: 120.21, xs: [576.72, 781.2, 985.68, 1190.16] };


/* ── timing ────────────────────────────────────────────────────────────── */
export const BOOT_TOTAL = 3.5;
const S1 = 1.2, S2 = 1.4, S3 = 0.9;   // Patch · Strike · Settle

/* ── motion ────────────────────────────────────────────────────────────── */
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const seg = (t, a, b) => clamp((t - a) / (b - a), 0, 1);
const mix = (a, b, t) => a + (b - a) * t;
const enter = (t) => 1 - Math.pow(1 - t, 3);
const draw = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const hash = (n) => { const s = Math.sin(n * 12.9898) * 43758.5453; return s - Math.floor(s); };

export const BOOT_SCALE = 3.4;   // logo scale while the rig is coming up
const BOOT_LIFT = 66;            // optical centring while the copy is hidden

const LIT = {
  scan: 0, extinguish: 1, morph: 1, mark: 1, slats: 1, logic: 1,
  rules: [1, 1], word: [1, 1, 1, 1, 1, 1, 1], flare: 0, beam: 0, t: 0,
};

// K is the theatrical intensity (0..1) — how far the glow, wash, flare and
// beam are pushed. 0.7 is the tuned default.
export function phaseAt(time, K = 0.7) {
  const s = {
    glow: 0, wash: 0, scale: BOOT_SCALE, lift: BOOT_LIFT,
    readout: 0, readoutText: '', h1: 0, sub: 0, status: 0,
    headerLit: 0.12, navLit: 0.18,
    logo: null,
  };

  if (time < S1) {                                    // ── Patch
    const p = time / S1;
    const scan = enter(seg(p, 0, 0.55));
    const ext = draw(seg(p, 0.5, 0.95));
    s.readout = seg(p, 0.08, 0.2) * (1 - seg(p, 0.72, 0.9));
    s.readoutText = ext > 0.5 ? 'patch resolved · 4 segments' : 'reading universe 001 · 512 ch';
    s.logo = {
      ...LIT, scan, extinguish: ext, morph: 0, mark: 0, slats: 0, logic: 0,
      rules: [0, 0], word: [0, 0, 0, 0, 0, 0, 0], flare: 0, beam: 0, t: time,
    };
    return s;
  }

  if (time < S1 + S2) {                               // ── Strike
    const lt = time - S1;
    const p = lt / S2;
    // lamp-strike stutter: two dropped beats as the arc catches
    const stut = p > 0.28 && p < 0.42
      ? (hash(Math.floor(lt * 26) * 9.7) > 0.34 ? 1 : 0.25) : 1;
    s.wash = enter(seg(p, 0.26, 0.5)) * (1 - 0.5 * seg(p, 0.7, 1)) * K;
    s.glow = enter(seg(p, 0.28, 0.5)) * K;
    s.logo = {
      scan: 1, extinguish: 1,
      morph: draw(seg(p, 0.02, 0.24)),
      mark: enter(seg(p, 0.28, 0.5)) * stut,
      slats: draw(seg(p, 0.4, 0.74)),
      logic: seg(p, 0.44, 0.8),
      rules: [seg(p, 0.2, 0.44), seg(p, 0.28, 0.52)],
      word: WORD.map((_, i) => enter(seg(p, 0.56 + i * 0.035, 0.63 + i * 0.035))),
      flare: enter(seg(p, 0.26, 0.35)) * (1 - 0.85 * draw(seg(p, 0.35, 0.74))) * K,
      beam: seg(p, 0.3, 0.4) * (1 - draw(seg(p, 0.42, 0.8))) * K,
      t: lt,
    };
    return s;
  }

  const lt = Math.min(time - S1 - S2, S3);            // ── Settle
  const p = lt / S3;
  const land = draw(seg(p, 0.02, 0.64));
  s.scale = mix(BOOT_SCALE, 1, land);
  s.lift = BOOT_LIFT * (1 - land);
  s.wash = 0.5 * K * (1 - draw(seg(p, 0, 0.6)));
  s.glow = K * (1 - draw(seg(p, 0, 0.58)));
  s.headerLit = mix(0.12, 1, enter(seg(p, 0.1, 0.52)));
  s.navLit = mix(0.18, 1, enter(seg(p, 0.16, 0.6)));
  s.h1 = enter(seg(p, 0.34, 0.66));
  s.sub = enter(seg(p, 0.5, 0.82));
  s.status = enter(seg(p, 0.68, 0.96));
  s.logo = { ...LIT, flare: 0.15 * K * (1 - enter(seg(p, 0, 0.45))), t: lt };
  return s;
}

/* ── one clock for the whole shell ─────────────────────────────────────── */
// Home starts the boot on mount; Header reads the same phase so the lockup and
// nav come up with the rig. Outside a provider both render the settled frame,
// so the components still work standalone.
const SETTLED = phaseAt(BOOT_TOTAL);
const BootContext = React.createContext(null);

export function BootProvider({ children, intensity = 0.7 }) {
  const [t, setT] = React.useState(BOOT_TOTAL);   // settled until a boot starts
  const raf = React.useRef(0);

  const start = React.useCallback(() => {
    cancelAnimationFrame(raf.current);
    const reduced = typeof window !== 'undefined' && window.matchMedia
      && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduced) { setT(BOOT_TOTAL); return; }   // settled frame, no motion
    const t0 = performance.now();
    setT(0);
    const tick = (now) => {
      const e = (now - t0) / 1000;
      setT(Math.min(e, BOOT_TOTAL));
      if (e < BOOT_TOTAL) raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, []);

  React.useEffect(() => () => cancelAnimationFrame(raf.current), []);

  const value = React.useMemo(
    () => ({ t, phase: phaseAt(t, intensity), start }),
    [t, intensity, start]
  );
  return <BootContext.Provider value={value}>{children}</BootContext.Provider>;
}

export function useBoot() {
  return React.useContext(BootContext)
    || { t: BOOT_TOTAL, phase: SETTLED, start: () => {} };
}

/* ── the channel grid, in logo coordinates ─────────────────────────────── */
const GX = 20, GPITCH = 40, GCELL = 34, GCOLS = 33;
const GY = 80, GRPITCH = 66, GRCELL = 56, GROWS = 12;
const TARGET_ROW = 9;
const SEG_COLS = [[14, 17], [19, 22], [24, 27], [29, 32]];
const SUB = SEG.w / 4;

// app tokens — src/styles/global.css @theme
const RED = '#ed1c24';
const BRAND = 'oklch(60% 0.23 27)';
const BRANDHI = 'oklch(68% 0.22 27)';
const GEL = 'oklch(75% 0.13 215)';
const ONLINE = 'oklch(72% 0.15 150)';
const WARN = 'oklch(78% 0.15 80)';

function survivorTarget(col) {
  for (let k = 0; k < 4; k++) {
    const [c0, c1] = SEG_COLS[k];
    if (col >= c0 && col <= c1) return SEG.xs[k] + (col - c0) * SUB;
  }
  return null;
}

function ChannelGrid({ scan, extinguish, morph, t }) {
  if (scan <= 0 || morph >= 1) return null;
  const cells = [];
  const flickFrame = Math.floor(t * 22);
  for (let r = 0; r < GROWS; r++) {
    for (let c = 0; c < GCOLS; c++) {
      const h = hash(c * 7.13 + r * 31.7);
      const on = seg(scan, h * 0.72, h * 0.72 + 0.18);
      if (on <= 0) continue;
      const tx = r === TARGET_ROW ? survivorTarget(c) : null;
      const surv = tx !== null;
      const rowDist = Math.abs(r - TARGET_ROW) / TARGET_ROW;
      let alpha, fill;
      if (surv) {
        alpha = mix(0.55, 1, extinguish);
        fill = extinguish > 0.35 ? RED : (h < 0.74 ? GEL : h < 0.9 ? ONLINE : WARN);
      } else {
        const die = seg(extinguish, mix(0.05, 0.55, 1 - rowDist), mix(0.45, 0.95, 1 - rowDist));
        alpha = (1 - die) * mix(0.2, 0.5, hash(c * 3.1 + r * 5.9));
        fill = h < 0.74 ? GEL : h < 0.9 ? ONLINE : h < 0.975 ? WARN : BRAND;
      }
      if (alpha <= 0.004) continue;
      const jit = extinguish > 0.7 ? 1 : mix(0.62, 1, hash(c * 13.7 + r * 5.3 + flickFrame * 17.1));
      cells.push(
        <rect
          key={r + '-' + c}
          x={surv ? mix(GX + c * GPITCH, tx, morph) : GX + c * GPITCH}
          y={surv ? mix(GY + r * GRPITCH, SEG.y, morph) : GY + r * GRPITCH}
          width={surv ? mix(GCELL, SUB, morph) : GCELL}
          height={surv ? mix(GRCELL, SEG.h, morph) : GRCELL}
          rx={surv ? mix(3, 0, morph) : 3}
          fill={fill}
          opacity={alpha * on * jit}
        />
      );
    }
  }
  return <g>{cells}</g>;
}

/* ── the mark ──────────────────────────────────────────────────────────── */
// `state` is phaseAt().logo; pass BOOT_MARK_LIT for a static, fully lit mark
// (the header lockup).
export const BOOT_MARK_LIT = LIT;

export function BootMark({ state, uid = 'f12' }) {
  const s = state;
  const wipeW = 459.29 + (1353.6 - 459.29) * draw(s.logic);
  return (
    <svg viewBox={'0 0 ' + VB.w + ' ' + VB.h} width="100%" height="100%"
         style={{ display: 'block', overflow: 'visible' }} aria-hidden="true">
      <defs>
        <radialGradient id={'f12flare' + uid} cx="0.5" cy="0.5" r="0.5">
          <stop offset="0%" stopColor={BRANDHI} stopOpacity="0.95" />
          <stop offset="35%" stopColor={BRAND} stopOpacity="0.35" />
          <stop offset="100%" stopColor={BRAND} stopOpacity="0" />
        </radialGradient>
        <linearGradient id={'f12beam' + uid} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor={BRANDHI} stopOpacity="0.5" />
          <stop offset="100%" stopColor={BRAND} stopOpacity="0" />
        </linearGradient>
        <clipPath id={'f12wipe' + uid}>
          <rect x="459.29" y="370" width={Math.max(0, wipeW - 459.29)} height="270" />
        </clipPath>
      </defs>

      {s.beam > 0 && (
        <polygon points="290,400 1400,150 1400,760"
                 fill={'url(#f12beam' + uid + ')'} opacity={s.beam * 0.8} />
      )}

      <g opacity={s.mark} fill={RED}>
        {MARK_BODY.map((d, i) => <path key={i} d={d} />)}
      </g>

      <g fill={RED}>
        {MARK_SLATS.map((d, i) => {
          const a = i / (MARK_SLATS.length + 4);
          return <path key={i} d={d} opacity={s.slats === 1 ? 1 : enter(seg(s.slats, a, a + 0.3))} />;
        })}
      </g>

      {s.flare > 0 && (
        <ellipse cx="252" cy="405" rx="430" ry="430"
                 fill={'url(#f12flare' + uid + ')'} opacity={s.flare} />
      )}

      <g fill={RED}>
        {WORD.map((d, i) => <path key={i} d={d} opacity={s.word[i]} />)}
      </g>

      <g clipPath={'url(#f12wipe' + uid + ')'}>
        {LOGIC.map((d, i) => <path key={i} d={d} fill={RED} />)}
      </g>

      {[RULE_TOP, RULE_BOT].map((r, i) => {
        const k = draw(s.rules[i]);
        const cx = r.x + r.w / 2;
        return (
          <rect key={i} x={r.x} y={r.y} width={r.w} height={r.h} fill={RED}
                transform={'translate(' + cx + ' 0) scale(' + k + ' 1) translate(' + (-cx) + ' 0)'} />
        );
      })}

      <g opacity={s.morph}>
        {SEG.xs.map((x, i) => (
          <rect key={i} x={x} y={SEG.y} width={SEG.w} height={SEG.h} fill={RED} />
        ))}
      </g>

      <ChannelGrid scan={s.scan} extinguish={s.extinguish} morph={s.morph} t={s.t} />
    </svg>
  );
}
